[metadata] {"type": "create", "filePath": "/workspace/repo/homeassistant/components/smlight/light.py", "content": """"Support for the SMLIGHT Ultima ambilight LED strip."""

from __future__ import annotations

from typing import Any

from pysmlight.const import AMBI_EFFECT_LIST, AmbiEffect, Pages
from pysmlight.exceptions import SmlightConnectionError
from pysmlight.models import AmbilightPayload

from homeassistant.components.light import (
    ATTR_BRIGHTNESS,
    ATTR_EFFECT,
    ATTR_RGB_COLOR,
    ColorMode,
    LightEntity,
    LightEntityFeature,
)
from homeassistant.core import HomeAssistant
from homeassistant.exceptions import HomeAssistantError
from homeassistant.helpers.entity_platform import AddConfigEntryEntitiesCallback
from homeassistant.util import color as color_util

from .const import DOMAIN
from .coordinator import SmConfigEntry, SmDataUpdateCoordinator
from .entity import SmEntity

PARALLEL_UPDATES = 1


async def async_setup_entry(
    hass: HomeAssistant,
    entry: SmConfigEntry,
    async_add_entities: AddConfigEntryEntitiesCallback,
) -> None:
    """Set up the SMLIGHT Ultima ambilight from a config entry."""
    coordinator = entry.runtime_data.data

    if coordinator.data.info.has_peripherals:
        async_add_entities([SmLightEntity(coordinator)])


class SmLightEntity(SmEntity, LightEntity):
    """Representation of the SMLIGHT Ultima ambilight LED strip."""

    coordinator: SmDataUpdateCoordinator

    _attr_translation_key = "ambilight"
    _attr_icon = "mdi:led-strip"
    _attr_supported_color_modes = {ColorMode.RGB}
    _attr_color_mode = ColorMode.RGB
    _attr_supported_features = LightEntityFeature.EFFECT
    _attr_effect_list = AMBI_EFFECT_LIST

    def __init__(self, coordinator: SmDataUpdateCoordinator) -> None:
        """Initialize the ambilight entity."""
        super().__init__(coordinator)
        self._attr_unique_id = f"{coordinator.unique_id}-ambilight"

    async def async_added_to_hass(self) -> None:
        """Register the SSE page callback for ambilight updates."""
        await super().async_added_to_hass()
        self.async_on_remove(
            self.coordinator.client.sse.register_page_cb(
                Pages.API2_PAGE_AMBILIGHT, self.coordinator.update_ambilight
            )
        )

    @property
    def _ambilight(self) -> AmbilightPayload:
        """Return the current ambilight state."""
        return self.coordinator.data.sensors.ambilight or AmbilightPayload()

    @property
    def is_on(self) -> bool:
        """Return true if the ambilight is on."""
        mode = self._ambilight.ultLedMode
        if mode is None:
            return False
        return mode != AmbiEffect.WSULT_OFF

    @property
    def brightness(self) -> int | None:
        """Return the brightness of the ambilight."""
        return self._ambilight.ultLedBri

    @property
    def effect(self) -> str | None:
        """Return the current effect."""
        if not self.is_on:
            return None
        try:
            return self._attr_effect_list[self._ambilight.ultLedMode]
        except (IndexError, TypeError):
            return None

    @property
    def rgb_color(self) -> tuple[int, int, int] | None:
        """Return the RGB color of the ambilight."""
        color = self._ambilight.ultLedColor
        if not color:
            return None
        try:
            red, green, blue = color_util.rgb_hex_to_rgb_list(color.lstrip("#"))
        except ValueError:
            return None
        return (red, green, blue)

    async def async_turn_on(self, **kwargs: Any) -> None:
        """Turn on the ambilight."""
        payload = AmbilightPayload()

        if ATTR_EFFECT in kwargs:
            effect = kwargs[ATTR_EFFECT]
            if effect not in self._attr_effect_list:
                return
            payload.ultLedMode = AmbiEffect(self._attr_effect_list.index(effect))
        elif not self.is_on:
            payload.ultLedMode = AmbiEffect.WSULT_SOLID

        if ATTR_BRIGHTNESS in kwargs:
            payload.ultLedBri = kwargs[ATTR_BRIGHTNESS]

        if ATTR_RGB_COLOR in kwargs:
            red, green, blue = kwargs[ATTR_RGB_COLOR]
            payload.ultLedMode = AmbiEffect.WSULT_SOLID
            payload.ultLedColor = f"#{red:02x}{green:02x}{blue:02x}"

        if payload == AmbilightPayload():
            return

        await self._async_send(payload)

    async def async_turn_off(self, **kwargs: Any) -> None:
        """Turn off the ambilight."""
        await self._async_send(AmbilightPayload(ultLedMode=AmbiEffect.WSULT_OFF))

    async def _async_send(self, payload: AmbilightPayload) -> None:
        """Send an ambilight command to the device."""
        try:
            await self.coordinator.client.actions.ambilight(payload)
        except SmlightConnectionError as err:
            raise HomeAssistantError(
                translation_domain=DOMAIN,
                translation_key="command_failed",
            ) from err
